from __future__ import annotations

import logging
import os
from abc import ABCMeta, abstractmethod

import paramiko
from taf.internal.impact_radar import log_radar

# TODO Remove it after deprecation
from .deprecate import deprecated
from .exceptions import (
    CommandExecutionError,
    CommandOutputCollectionError,
    ConnectFailedError,
    ConnectionError,
    FileProtocolClientError,
)
from .fileprotocol import file_protocol
from .process import SSHProcess
from .proxy import ParaProxy
from .workarounds import handle_exit_signal, try_method_none

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


LOGGER_NAME_FMT = "taf.transport.ssh.connection.{repr}"
LOGGER_FORMATTER = logging.Formatter(
    "[%(created)s][%(name)s][%(levelname)s][%(module)s][%(lineno)d] %(message)s"
)


def connect(
    hostname,
    username,
    password=None,
    port=None,
    key_path=None,
    pkey=None,
    timeout=None,
    proxy=None,
    look_for_keys=True,
    allow_agent=True,
):
    """Create new connection object, configure and open the connection to the
    remote host.

    The proxy parameter should be, if it is given, an instance that inherits
    from Connection class. The new connection will be routed through the given
    object.

    The ``key_path`` parameter specifies the path to key that should be used
    to authenticate with the remote.

    From Paramiko docs:

        Authentication is attempted in the following order of priority:
        - The pkey or key_filename passed in (if any)
        - Any key we can find through an SSH agent
        - Any “id_rsa”, “id_dsa” or “id_ecdsa” key discoverable in ~/.ssh/
        - Plain username/password auth, if a password was given

    If a private key requires a password to unlock it, and a password is
    passed in, that password will be used to attempt to unlock the key.

    :param str hostname: The hostname of the remote to connect to.
    :param str | None username: Username that should be used in authentication.
    :param str | None password: (optional) Password that will be used in
        authentication and to try to decrypt the private key, if needed.
    :param int | None port: (optional) The port of the remote host, that the
        connection will be opened on. By default SSH uses ``22``.
    :param str | list[str] | None key_path: (optional) A path, or a list of
        paths to the files with private keys,that will be tried during
        authentication.
    :param parmiko.Pkey | None pkey: (optional) PKey object containing a
        private key to use during authentication.
    :param float | None timeout: (optional) Timeout in seconds for the TCP
        connect (``None`` by default). Also used in initiating the file
        protocol client (:py:attr:`files` property of the returned instance)
        and retrieving SSH protocol banner.
    :param Connection | None proxy: (optional) Existing connection and opened
        to the remote host, from which the new connection will be started.
    :param bool look_for_keys: (optional) ``True`` by default. Set to ``False``
        to disable searching for discoverable private key files in ``~/.ssh/``
    :param bool allow_agent: (optional) ``True`` by default. Set to ``False``
        to disable asking the SSH agent for private keys

    :return: :py:class:`ProxySSHConnection` if proxy argument was given,
        or :py:class:`SSHConnection` otherwise. The returned object is already
        configured and working.

    :raise ConnectFailedError: If authentication fails, host refuses the
        connection, connecting times out or the given proxy is not connected.

    """
    parameters = {
        "hostname": hostname,
        "username": username,
        "password": password,
        "key_path": key_path,
        "pkey": pkey,
        "timeout": timeout,
        "banner_timeout": timeout,
        "look_for_keys": look_for_keys,
        "allow_agent": allow_agent,
    }
    if port is not None:
        parameters["port"] = port

    if proxy is None:
        new_connection = SSHConnection()
    else:
        new_connection = ProxySSHConnection()
        parameters["proxy"] = proxy

    new_connection.configure(**parameters)
    new_connection.connect()
    return new_connection


class Connection:
    """Base abstraction class that other SSH connection classes subclass from.

    The documentation of the methods serves as a list of invariants that are
    assumed to be true when calling a subroutine of a subclass of this class.

    The deprecated parts of this class should be omitted when implementing a
    subclass.

    tested_params - a dictionary that defines which fields in self.params are
        tested for being None. If any of its keys doesn't exist in self.params,
        ConnectFailedError is raised with the key's value as a message.
    """

    __metaclass__ = ABCMeta
    tested_params = {
        "hostname": "cannot connect: no hostname given.",
        "username": "cannot connect: no username given.",
        "port": "cannot connect: no port given.",
    }
    default_port = None
    default_timeout = None

    def __init__(self):
        self._is_connected = False
        self.params = {}
        self.params["port"] = self.default_port
        self.params["timeout"] = self.default_timeout
        self.params["banner_timeout"] = self.default_timeout
        self.params["key_path"] = None
        self.params["pkey"] = None
        self.params["look_for_keys"] = True
        self.params["allow_agent"] = True
        self._last_process = None

    @property
    @deprecated("SSHProcess", sphinx_directive=":py:class:")
    def last_process(self):
        if not self.command_sent:
            raise CommandOutputCollectionError("no command sent yet.")
        return self._last_process

    @property
    @deprecated("SSHProcess.stdin", sphinx_directive=":py:attr:")
    def last_stdin(self):
        return self.last_process.stdin

    @property
    @deprecated("SSHProcess.stdout", sphinx_directive=":py:attr:")
    def last_stdout(self):
        return self.last_process.stdout

    @property
    @deprecated("SSHProcess.stderr", sphinx_directive=":py:attr:")
    def last_stderr(self):
        return self.last_process.stderr

    @abstractmethod
    def connect(self):
        """Establish a connection with a machine using given params.

        If :py:attr:`params` attribute has not been set, raise
        :py:class:`ConnectionError`. Methods that override this should call
        ``.check_if_connected()`` and ``._check_params()`` first.
        """
        raise NotImplementedError

    @abstractmethod
    def disconnect(self):
        """Destroy the connection and all of its subcomponents.

        Should never raise any exception.
        """
        raise NotImplementedError

    @abstractmethod
    def execute(self, command, timeout):
        """Send command, wait until it finishes and return the output.

        Should return both stdout and stderr, synchronised.
        """
        raise NotImplementedError

    @abstractmethod
    def send_command(self, command):
        """Send a command to the remote host."""
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.read_output()", sphinx_directive=":py:func:")
    def read_output(self):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.read_error()", sphinx_directive=":py:func:")
    def read_error(self):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.write_input()", sphinx_directive=":py:func:")
    def write_input(self, data):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.stdin.flush()", sphinx_directive=":py:func:")
    def flush_stdin(self):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.is_alive()", sphinx_directive=":py:func:")
    def execution_ended(self):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.join()", sphinx_directive=":py:func:")
    def await_execution_end(self, timeout):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.read_output_until()", sphinx_directive=":py:func:")
    def read_output_until(self, match, timeout=None):
        raise NotImplementedError

    @abstractmethod
    @deprecated("SSHProcess.read_error_until()", sphinx_directive=":py:func:")
    def read_error_until(self, match, timeout=None):
        raise NotImplementedError

    @property
    @abstractmethod
    def files(self):
        raise NotImplementedError

    @property
    @abstractmethod
    @deprecated("SSHProcess.get_exit_code()", sphinx_directive=":py:func:")
    def exit_code(self):
        raise NotImplementedError

    @property
    @abstractmethod
    def is_connected(self):
        """Should return ``True`` if connection is working, ``False`` otherwise."""
        raise NotImplementedError

    def _perform_preconnect_checks(self):
        for param_name, exc_msg in self.tested_params.items():
            if param_name not in self.params:
                raise ConnectFailedError(exc_msg)

    # TODO docstring here looks awful. Also, this probably should not exist.
    def configure(self, **kwargs):
        """
        Save ip and login credentials, but do not connect yet.

        :param str hostname: destination ip/hostname
        :param str username: user for whom connection to 'hostname' will be
                             initialized
        :param str password: user's password
        :param str port:
        :param str proxy_host: optional middle host ip/hostname.
        :param str proxy_username: if proxy_host defined, then user also should
                                   be provided
        :param str proxy_password: if proxy_host defined, then password also
                                   should be provided
        """
        self.params.update(kwargs)

    def _get_connection_params(self):
        return {
            "hostname": self.params["hostname"],
            "username": self.params["username"],
            "password": self.params["password"],
            "port": self.params["port"],
            "timeout": self.params["timeout"],
            "banner_timeout": self.params["banner_timeout"],
            "key_filename": self.params["key_path"],
            "pkey": self.params["pkey"],
            "look_for_keys": self.params["look_for_keys"],
            "allow_agent": self.params["allow_agent"],
        }


class SSHConnection(Connection):
    """Direct SSH connection.

    It is highly encouraged to use :py:func:`connect()` instead of
    instantiating this class directly.
    """

    # TODO: certificate management?
    default_port = 22
    default_timeout = 10

    def __init__(self):
        super().__init__()
        self._client = None
        self._file_protocol = None

    def connect(self):
        """Start the connection.

        If connection is already started - returns gracefully.

        :raises ConnectionError: Raised for all sorts of issues related
            to network problems and authentication. Also raised if the
            connection configuration is missing parameters.
        """
        if self.is_connected:
            logger.info("Instance is already connected: connect() ignored.")
            return

        self._perform_preconnect_checks()
        self._configure_client()
        self._connect_client()

    def _connect_client(self):
        connection_params = self._get_connection_params()

        assert self._client is not None

        log_channel = None
        log_path = os.getenv("TAF_SSH_TRANSPORT_DEBUG_LOG")
        if log_path is not None:
            log_channel = LOGGER_NAME_FMT.format(repr=repr(self))
            self._configure_debug_logging(log_channel, log_path)

        try:
            # TODO: Remove this as soon as paramiko does this for us.
            if not self._try_method_none(connection_params, log_channel):
                self._client.connect(**connection_params)
        except paramiko.AuthenticationException as exc:
            raise ConnectFailedError(
                f"authentication failed while connecting to "
                f"{connection_params['hostname']} on port {connection_params['port']} "
                f"via ssh."
            ) from exc
        except (OSError, paramiko.SSHException) as exc:
            raise ConnectFailedError(
                f"unable to connect to {connection_params['hostname']} on port "
                f"{connection_params['port']} via SSH."
            ) from exc

        # Make sure the client supports 'exit-signal' information
        transport = self._client.get_transport()
        assert transport is not None
        handle_exit_signal(transport)
        self.is_connected = True

    def _configure_debug_logging(self, log_channel, log_path):
        assert self._client is not None
        logger = logging.getLogger(log_channel)
        logger.setLevel(logging.DEBUG)
        file_handler = logging.FileHandler(log_path)
        file_handler.setFormatter(LOGGER_FORMATTER)
        logger.addHandler(file_handler)
        self._client.set_log_channel(log_channel)

    def _try_method_none(self, params, transport_log_channel):
        return try_method_none(logger, transport_log_channel, self._client, **params)

    def _configure_client(self):
        self._client = paramiko.SSHClient()
        self._client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    def invoke_shell(
        self,
        term="vt100",
        width=None,
        height=None,
        width_pixels=None,
        height_pixels=None,
        environment=None,
    ):
        """
        Initiate an interactive shell session on the SSH server.

        Opens a new `paramiko.Channel` connected to a pseudo-terminal
        with the specified terminal type and dimensions.

        See `RFC 4254 section 6.2
        <https://datatracker.ietf.org/doc/html/rfc4254#autoid-12>`_:

            Zero dimension parameters MUST be ignored. The character/row
            dimensions override the pixel dimensions (when nonzero). Pixel
            dimensions refer to the drawable area of the window.

            The dimension parameters are only informational.

        :param str | None term: (optional) Terminal emulation type,
                                ``'vt100'`` by default.
        :param int | None width: (optional) Terminal window width in
                                 characters, ``80`` by default.
        :param int | None height: (optional) Terminal window height in
                                  characters, ``24`` by default.
        :param int | None width_pixels: (optional) Terminal window width in
                                        pixels, ``0`` by default.
        :param int | None height_pixels: (optional) Terminal window height in
                                         pixels, ``0`` by default.
        :param dict | None environment: (optional) Environment variables for
                                        the shell session.

        :raises SSHException: If the server cannot start a shell

        :returns paramiko.Channel: a new channel linked to the remote shell
        """
        shell_params = {
            "term": term,
            "width": width,
            "height": height,
            "width_pixels": width_pixels,
            "height_pixels": height_pixels,
            "environment": environment,
        }
        shell_params = {k: v for k, v in shell_params.items() if v is not None}
        return self._client.invoke_shell(**shell_params)

    def invoke_direct_tcpip(
        self, destination_address, source_address=("", 0), timeout=None
    ):
        transport = self._client.get_transport()
        return transport.open_channel(
            "direct-tcpip", destination_address, source_address, timeout=timeout
        )

    def disconnect(self):
        """Tear down the session and close the connection.

        If any :py:class:`ProxySSHConnection` objects are using this connection
        as a proxy, they should be disconnected first.

        If connection is already closed - returns gracefully.
        """
        logger.debug("Disconnecting %s", self._to_string_short())
        self._disconnect_file_protocol_client()
        self._disconnect_ssh_client()

    def execute(self, command, timeout=None):
        """Send a command, wait until it finishes, return the output.

        :param str command: Command to execute.
        :param float | None timeout: (optional) The maximum time to wait for
            the process to finish.

        :raises CommandOutputTimeoutError: If the process execution time
            exceeds the timeout; see :py:func:`SSHProcess.join()`.

        :returns str: Combined stdout and stderr of the process.
        """
        process = self.send_command(command, get_pty=True, timeout=timeout)
        process.join(timeout=timeout)
        # TODO: Remove read_error() and test if it didn't break something
        output = process.read_error() + process.read_output()
        return output

    def _disconnect_file_protocol_client(self):
        if self._file_protocol is None:
            return
        logger.info("Closing FP client.")
        try:
            self._file_protocol.close()
        except Exception:
            logger.exception(
                "File protocol raised an exception while closing. "
                "Instance: %s, protocol: %r",
                self._to_string_short(),
                self._file_protocol,
            )
        finally:
            self._file_protocol = None

    def _disconnect_ssh_client(self):
        if self._client is None:
            return
        try:
            self._client.close()
        except Exception:
            logger.exception(
                "Connection raised an exception while disconnecting. Instance: %s",
                self,
            )
        finally:
            self._client = None
            self.is_connected = False

    def send_command(self, command, bufsize=-1, timeout=None, get_pty=False):
        """Send command to the remote host.

        In comparison to :py:func:`SSHConnection.execute()`, this method does
        not block until the executed command finishes.

        Use the returned :py:func:`SSHProcess` object to control the process,
        read its stdout/stderr, write to stdin, get the exit code, etc.

        This method does not block.

        :param str command: Command to send to the remote host.
        :param int | None bufsize: (optional) Buffer size used by the
            connection for reads of the received stdout/stderr data and writes
            to the remote stdin. Has the same semantics and meaning as Python's
            built-in ``file()`` function.
        :param float | None timeout: (optional) Default timeout (in seconds)
            used for the reads/writes. Note, this is not the maximum time for
            the process execution.
        :param bool get_pty: (optional) Request a pseudo-terminal from the
            server for the execution of this command. ``False`` by default.
            Passing ``True`` will result, among other things, in the stdout and
            stderr being combined and the order of the lines between these
            streams being preserved. Only reads from stdout will return data;
            reads from stderr will return an empty string.

        :returns: :py:class:`SSHProcess` - the object representation of the
            started remote process.
        """
        self._verify_connection(
            "cannot send command: not connected.", CommandExecutionError
        )

        log_radar(
            f"Sending command: {command}",
            command=command,
            connection=self.address,
            proxies=self.proxies,
        )

        io_tuple = self._client.exec_command(
            command, bufsize=bufsize, timeout=timeout, get_pty=get_pty
        )
        self._last_process = SSHProcess(*io_tuple)
        return self._last_process

    @property
    @deprecated("SSHProcess", sphinx_directive=":py:class:")
    def command_sent(self):
        """``True`` if a command has been sent already; ``False`` otherwise.

        A boolean representing whether other ``last_*`` properties are
        available, i.e. whether any command has been issued via this connection.
        """
        return self._last_process is not None

    @deprecated("SSHProcess.read_output()", sphinx_directive=":py:func:")
    def read_output(self, size=None):
        """Return the contents of the stdout stream of the last sent command.

        If ``size`` is given, the method will block until the indicated number
        of bytes is available, i.e. until there is enough data streamed out by
        the process onto stdout.

        If ``size`` is not given, this method will block until the remote
        process to finishes execution, or a timeout occurs.

        :param int | None size: (optional) Read at most ``size`` bytes from the
            buffer.
        """
        return self.last_process.read_output(size=size)

    @deprecated("SSHProcess.read_error()", sphinx_directive=":py:func:")
    def read_error(self, size=None):
        """Return the contents of the stderr stream of the last sent command.

        If ``size`` is given, the method will block until the indicated number
        of bytes is available, i.e. until there is enough data streamed out by
        the process onto stderr.

        If ``size`` is not given, this method will block until the remote
        process to finishes execution, or a timeout occurs.

        :param int | None size: (optional) Read at most ``size`` bytes from the
            buffer.
        """
        return self.last_process.read_error(size=size)

    @deprecated("SSHProcess.read_output_until()", sphinx_directive=":py:func:")
    def read_output_until(self, match, timeout=None):
        """
        Read the stdout stream of the last command until the pattern string occurs.

        The pattern string will be included in the returned output.

        :param str pattern: Pattern to match.
        :param float | None timeout: Number of seconds after which a timeout
            exception will be raised.

        :returns: Output read up to and including the ``pattern`` string.
        """
        return self.last_process.read_output_until(match, timeout)

    @deprecated("SSHProcess.read_error_until()", sphinx_directive=":py:func:")
    def read_error_until(self, match, timeout=None):
        """
        Read the stderr stream of the last command until the pattern string occurs.

        The pattern string will be included in the returned output.

        :param str pattern: Pattern to match.
        :param float | None timeout: Number of seconds after which a timeout
            exception will be raised.

        :returns: Error output read up to and including the ``pattern`` string.
        """
        return self.last_process.read_error_until(match, timeout)

    @deprecated("SSHProcess.write_input()", sphinx_directive=":py:func:")
    def write_input(self, data):
        """Write data onto the stdin stream of the last command."""
        self.last_process.write_input(data)

    @deprecated("SSHProcess.stdin.flush()", sphinx_directive=":py:func:")
    def flush_stdin(self):
        """Flush the input channel buffer.

        Use this to ensure that the input data is sent out at the point of the
        call to this method.
        """
        self.last_process.stdin.flush()

    @property
    @deprecated("SSHProcess.get_exit_code()", sphinx_directive=":py:func:")
    def exit_code(self):
        """Return the exit code of the last executed command."""
        return self.last_process.get_exit_code()

    @deprecated("SSHProcess.is_alive()", sphinx_directive=":py:func:")
    def execution_ended(self):
        """Return ``True`` if an execution of the command ended, ``False`` otherwise.

        This subroutine is non-blocking.
        """
        return not self.last_process.is_alive()

    @deprecated("SSHProcess.join()", sphinx_directive=":py:func:")
    def await_execution_end(self, timeout=None):
        """Block until an execution of the command finishes."""
        self.last_process.join()

    @property
    def files(self):
        """Access the file transfer client.

        Depending on which protocol is available on the server, returns either:

        * :py:class:`SFTP`, if the server has the SFTP subsystem implemented
            and permits it.
        * :py:class:`SCP` otherwise.

        The initial connection opening timeout of this object will be used as
        the timeout for initiating the file protocol client.

        :raises FileProtocolClientError: If initialization of the client
            failed, or the connection is closed.
        """
        if not self.is_connected:
            raise FileProtocolClientError(
                "initializing file protocol client failed: ssh client disconnected."
            )
        if self._file_protocol is None:
            opening_timeout = self.params.get("timeout")
            self._file_protocol = file_protocol(self._client, timeout=opening_timeout)
        return self._file_protocol

    # TODO this should raise ConnectionError, not CEE
    # TODO this should use proper exception chaining
    def keep_alive(self):
        """Send a packet that will be ignored by the host.

        :raises CommandExecutionError: if the TCP stack indicated that the
            connection is closed after sending this packet, i.e. an EOF occured.
        """
        logger.debug("Sending keep alive packet via %s", self._to_string_short())

        if not self._is_connected:
            msg = "'keep alive' packet sending failed: not connected."
            raise CommandExecutionError(msg)
        try:
            transport = self._client.get_transport()
            transport.send_ignore()
        except EOFError as exc:
            self.is_connected = False
            logger.error("EOFError while sending keep-alive!")
            raise CommandExecutionError(
                "'keep alive' packet sending failed: connection dropped."
            ) from exc
        logger.debug("Keep alive packet sent.")

    # TODO this should use proper exception chaining
    # XXX this (i.e. the whole call stack here) should NEVER use __str__
    # Usage of __str__() here, or any of the calls that call __str__(), leads
    # to indefinite recurrence. Use _to_string_short or self.address instead.
    @property
    def is_connected(self):
        """Return ``True`` if this SSH session is open; ``False`` otherwise.

        Will perform basic connection checks at the point of attribute access.
        Most notably, accessing this property triggers a sending of a
        keep-alive packet, to improve accuracy of the result. See
        :py:func:`keep_alive()`.
        """
        if not self._is_connected:
            return False

        if not self._connection_is_working():
            self.disconnect()
            return False
        return True

    def _connection_is_working(self):
        """Perform simple connection checks

        Checks paramiko.Transport of the internal client object, and sends a
        keep-alive. If any check fails, return False, True otherwise.
        """
        logger.debug("Checking connection to %s.", self.address)

        transport = self._client.get_transport()
        if transport is None:
            logger.warning("Found a broken connection with an uninitialized transport.")
            logger.debug("Connection: %r", self)
            return False
        if not transport.is_alive():
            logger.debug("Broken connection (dead transport): %r.", self)
            return False
        try:
            self.keep_alive()
        except CommandExecutionError:
            logger.exception("Connection check failed on sending a keep-alive.")
            return False
        return True

    # TODO: This probably shouldn't exist.
    @is_connected.setter
    def is_connected(self, value):
        self._is_connected = value

    def _verify_connection(self, exc_msg, exc_class):
        if not self.is_connected:
            raise exc_class(exc_msg)

    def __str__(self):
        string = self._to_string_short() + "\n"
        string += f"Connected: {'yes' if self.is_connected else 'no'}\n"
        string += "Parameters:\n"
        for key, value in self.params.items():
            if key == "password" or key == "pkey":
                continue
            param_line = f"\t{key}: {value}\n"
            param_line = "\t\t".join(param_line.splitlines(True))
            string += param_line
        string = string[:-1]
        return string

    def __repr__(self):
        return super().__repr__().rstrip(">") + " (" + self.address + ")>"

    def _to_string_short(self):
        return "SSH connection: " + self.address

    @property
    def address(self):
        username = self.params["username"]
        hostname = self.params["hostname"]
        port = self.params["port"]
        return username + "@" + hostname + ":" + str(port)

    @property
    def proxies(self) -> list[str]:
        """Return a list of addresses of all proxies used by this connection.

        For a chain of SSH connections which could be represented as

            connection: {host: <ip>, proxy: {host: <proxy_ip_1>, proxy: {host: <proxy_ip_2>, proxy: {...}}}

        the output list for the connection at hand will be

            [<proxy_ip_1>, <proxy_ip_2>, ...]
        """
        proxy: SSHConnection | ProxySSHConnection | None = self.params.get("proxy")
        if not proxy:
            return []
        return [proxy.address] + proxy.proxies


class ProxySSHConnection(SSHConnection):
    """Represents an SSH connection that is tunneled through another one.

    It is highly encouraged to use :py:func:`connect()` instead of
    instantiating this class directly.

    Subclass of :py:class:`SSHConnection`; has roughly the same interface
    semantics as its parent class.

    Requires the proxy host to provide netcat utility to the logged user; the
    proxy host has to have ``nc`` command available.

    Requires `proxy` parameter to be set to an object instance that the
    connection should be tunneled through.
    """

    default_port = 22

    # NOTE: A happy coincidence of using a remote command to create tcp tunnel
    # is that hostnames are resolved using the proxy knowledge, instead of
    # local one. Whenever the usage of netcat is removed from the library, a
    # separate mechanism for resolving hostnames must be put in place.
    tunneling_command = "nc {hostname} {port}"

    def __init__(self):
        self.proxy = None
        super().__init__()
        self.tested_params = dict(self.tested_params)
        self.tested_params["proxy"] = "cannot connect: no proxy given."

    @property
    def is_connected(self):
        """Return ``True`` if this SSH session is open; ``False`` otherwise.

        Will return ``False`` if the underlying proxy connection is not connected.

        Will perform basic connection checks at the point of attribute access.
        Most notably, accessing this property triggers a sending of a
        keep-alive packet, to improve accuracy of the result. See
        :py:func:`keep_alive()`.

        These checks will also be performed on the underlying proxy connection.
        """

        return SSHConnection.is_connected.fget(self) and not self.proxy.closed

    # TODO: This shouldn't be here.
    @is_connected.setter
    def is_connected(self, value):
        self._is_connected = value

    def connect(self):
        try:
            super().connect()
        except ConnectionError:
            if self.proxy is not None and not self.proxy.closed:
                self.proxy.close()
            raise

    def _try_method_none(self, params, transport_log_channel):
        result = super()._try_method_none(params, transport_log_channel)

        if not result:
            # Recreate proxy, since it was closed in try_method_none()
            params["sock"] = self._create_proxy()
        return result

    def _get_connection_params(self):
        connection_params = super()._get_connection_params()
        connection_params["sock"] = self._create_proxy()
        return connection_params

    def _create_proxy(self):
        tunneling_command = self.tunneling_command.format(**self.params)
        proxy = self.params["proxy"]
        tunnel_process = proxy.send_command(tunneling_command)
        tunnel_streams = (
            tunnel_process.stdin,
            tunnel_process.stdout,
            tunnel_process.stderr,
        )
        self.proxy = ParaProxy(*tunnel_streams)
        return self.proxy

    def _perform_preconnect_checks(self):
        super()._perform_preconnect_checks()
        if not self.params["proxy"].is_connected:
            raise ConnectFailedError("cannot create a tunnel: proxy connection dead.")
